		t.Fatalf("legacy listenPorts did not survive unmarshal: %#v", pkg.AffectedProcs)
	}
	if pkg.HasReachablePort() {
		t.Fatal("legacy strings alone must not indicate reachability")
	}
	pkg.AffectedProcs[0].ListenPortStats = []PortStat{{BindAddress: "127.0.0.1", Port: "22", PortReachableTo: []string{"127.0.0.1"}}}
	if !pkg.HasReachablePort() {
		t.Fatal("reachable PortStat was not found")
	}
}
